## 2. KNOWLEDGE GRAPH SCHEMA

```cypher
CREATE CONSTRAINT party_id IF NOT EXISTS FOR (p:Party) REQUIRE p.id IS UNIQUE;
CREATE CONSTRAINT loan_id IF NOT EXISTS FOR (l:Loan) REQUIRE l.id IS UNIQUE;

CREATE INDEX loan_status FOR (l:Loan) ON (l.status);
CREATE INDEX party_cs FOR (p:Party) ON (p.credit_score);

// Party: {id, name, credit_score:300-850, annual_revenue, sector, country, pd_estimate, is_listed:bool}
// Loan:  {id, principal, interest_rate, term_months, status:PERFORMING|DELINQUENT|DEFAULTED, ltv_ratio}

// Relationships
// (b:Party)-[:HAS_LOAN]->(l:Loan)
// (g:Party)-[:GUARANTEES {since_date:DATE, guarantee_amount:FLOAT}]->(l:Loan)
// (p:Party)-[:PARENT_OF {ownership_pct:FLOAT}]->(s:Party)

CALL gds.graph.project('credit_risk_graph', ['Party','Loan'], {
  HAS_LOAN:{orientation:'NATURAL'},
  GUARANTEES:{orientation:'NATURAL', properties:['guarantee_amount']},
  PARENT_OF:{orientation:'NATURAL', properties:['ownership_pct']},
  RELATED_TO:{orientation:'UNDIRECTED'}
});
```
